package com.moishow.identity;

import com.moishow.MoishowServerApplication;
import com.nimbusds.jose.*;import com.nimbusds.jose.crypto.RSASSASigner;import com.nimbusds.jwt.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.web.server.context.WebServerApplicationContext;
import org.springframework.context.*;import org.springframework.context.annotation.*;import org.springframework.security.oauth2.jwt.*;
import org.testcontainers.postgresql.PostgreSQLContainer;
import tools.jackson.databind.*;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.interfaces.*;import java.time.*;import java.util.*;

class AppleMobileAuthApiTest {
 static final String SERVICE="com.moishow.web",CALLBACK="https://api.example.com/api/v1/auth/apple/mobile/callback";
 static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");static ConfigurableApplicationContext context;static String base;
 static final HttpClient http=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build();static final ObjectMapper json=new ObjectMapper();static KeyPair keys;
 @Configuration @Profile("apple-mobile-test") static class Verification {
  @Bean @Primary SocialVerifier signedAppleVerifier(){var decoder=NimbusJwtDecoder.withPublicKey((RSAPublicKey)keys.getPublic()).build();decoder.setJwtValidator(JwtValidators.createDefaultWithIssuer("https://appleid.apple.com"));return (provider,token,nonce)->{try{var jwt=decoder.decode(token);ApiProblem.require(provider.equals("APPLE")&&jwt.getAudience().contains(SERVICE)&&Objects.equals(nonce,jwt.getClaimAsString("nonce"))&&jwt.getExpiresAt()!=null&&jwt.getExpiresAt().isAfter(Instant.now()),401,"INVALID_SOCIAL_TOKEN");return new SocialVerifier.Identity(provider,jwt.getSubject());}catch(JwtException e){throw new ApiProblem(401,"INVALID_SOCIAL_TOKEN");}};}
 }
 @BeforeAll static void start()throws Exception{var generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);keys=generator.generateKeyPair();postgres.start();context=new SpringApplicationBuilder(MoishowServerApplication.class,Verification.class).profiles("db","apple-mobile-test").properties("server.port=0","logging.level.root=ERROR","spring.main.banner-mode=off","APPLE_MOBILE_SERVICE_ID="+SERVICE,"APPLE_MOBILE_CALLBACK_URL="+CALLBACK,"AUTH_APPLE_CLIENT_IDS="+SERVICE).run("--spring.datasource.url="+postgres.getJdbcUrl(),"--spring.datasource.username="+postgres.getUsername(),"--spring.datasource.password="+postgres.getPassword());base="http://127.0.0.1:"+((WebServerApplicationContext)context).getWebServer().getPort()+"/api/v1/auth/apple/mobile";}
 @AfterAll static void stop(){if(context!=null)context.close();postgres.stop();}
 static HttpResponse<String> post(String path,Object body)throws Exception{return http.send(HttpRequest.newBuilder(URI.create(base+path)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
 static Map<String,String> query(String uri){var values=new HashMap<String,String>();for(var part:URI.create(uri).getRawQuery().split("&")){var pair=part.split("=",2);values.put(URLDecoder.decode(pair[0],StandardCharsets.UTF_8),URLDecoder.decode(pair[1],StandardCharsets.UTF_8));}return values;}
 static String challenge(String verifier)throws Exception{return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)));}
 static String jwt(String nonce,String audience,KeyPair signing)throws Exception{var jwt=new SignedJWT(new JWSHeader(JWSAlgorithm.RS256),new JWTClaimsSet.Builder().issuer("https://appleid.apple.com").audience(audience).subject("signed-apple-user").claim("nonce",nonce).issueTime(Date.from(Instant.now())).expirationTime(Date.from(Instant.now().plusSeconds(300))).build());jwt.sign(new RSASSASigner((RSAPrivateKey)signing.getPrivate()));return jwt.serialize();}
 static HttpResponse<String> callback(String state,String token)throws Exception{String body="state="+URLEncoder.encode(state,StandardCharsets.UTF_8)+"&id_token="+URLEncoder.encode(token,StandardCharsets.UTF_8);return http.send(HttpRequest.newBuilder(URI.create(base+"/callback")).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 @Test void pkceBoundOneUseTicketExchangesWithoutTokensInRedirect()throws Exception{String verifier="v".repeat(64);var started=post("/start",Map.of("codeChallenge",challenge(verifier)));assertEquals(200,started.statusCode(),started.body());var start=json.readTree(started.body());var params=query(start.path("authorizeUrl").asText());assertEquals("https://appleid.apple.com/auth/authorize",start.path("authorizeUrl").asText().split("\\?")[0]);assertEquals(SERVICE,params.get("client_id"));assertEquals(CALLBACK,params.get("redirect_uri"));assertEquals("form_post",params.get("response_mode"));String token=jwt(params.get("nonce"),SERVICE,keys);var redirected=callback(params.get("state"),token);assertEquals(302,redirected.statusCode(),redirected.body());String location=redirected.headers().firstValue("Location").orElseThrow();assertTrue(location.startsWith("moishow://apple/callback?"));assertFalse(location.contains(token));assertFalse(location.contains("id_token"));assertFalse(location.contains("code="));var handoff=query(location);assertEquals(401,post("/exchange",Map.of("ticket",handoff.get("ticket"),"codeVerifier","x".repeat(64))).statusCode());var exchanged=post("/exchange",Map.of("ticket",handoff.get("ticket"),"codeVerifier",verifier));assertEquals(200,exchanged.statusCode(),exchanged.body());assertEquals("ONBOARDING",json.readTree(exchanged.body()).path("scope").asText());assertEquals(401,post("/exchange",Map.of("ticket",handoff.get("ticket"),"codeVerifier",verifier)).statusCode());assertEquals(401,callback(params.get("state"),token).statusCode());}
 @Test void invalidSignedClaimsStateAndPkceAreRejected()throws Exception{assertEquals(400,post("/start",Map.of("codeChallenge","short")).statusCode());var p=query(json.readTree(post("/start",Map.of("codeChallenge",challenge("z".repeat(64)))).body()).path("authorizeUrl").asText());assertEquals(401,callback("unknown",jwt(p.get("nonce"),SERVICE,keys)).statusCode());assertEquals(401,callback(p.get("state"),jwt("wrong-nonce",SERVICE,keys)).statusCode());assertEquals(401,callback(p.get("state"),jwt(p.get("nonce"),"foreign-audience",keys)).statusCode());var generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);assertEquals(401,callback(p.get("state"),jwt(p.get("nonce"),SERVICE,generator.generateKeyPair())).statusCode());}
 @Test void expiredAttemptsAndTicketsAreRejected()throws Exception{var started=post("/start",Map.of("codeChallenge",challenge("q".repeat(64))));assertEquals(200,started.statusCode(),started.body());var p=query(json.readTree(started.body()).path("authorizeUrl").asText());var jdbc=context.getBean(org.springframework.jdbc.core.JdbcTemplate.class);jdbc.update("update apple_mobile_auth_attempt set expires_at=now()-interval '1 second' where state_hash=?",Crypto.hash(p.get("state")));assertEquals(401,callback(p.get("state"),jwt(p.get("nonce"),SERVICE,keys)).statusCode());var startedAgain=post("/start",Map.of("codeChallenge",challenge("q".repeat(64))));assertEquals(200,startedAgain.statusCode(),startedAgain.body());var second=query(json.readTree(startedAgain.body()).path("authorizeUrl").asText());var redirect=callback(second.get("state"),jwt(second.get("nonce"),SERVICE,keys));String ticket=query(redirect.headers().firstValue("Location").orElseThrow()).get("ticket");jdbc.update("update apple_mobile_auth_attempt set ticket_expires_at=now()-interval '1 second' where ticket_hash=?",Crypto.hash(ticket));assertEquals(401,post("/exchange",Map.of("ticket",ticket,"codeVerifier","q".repeat(64))).statusCode());}
}
